# HRM study notes (notes only: no MCQs, no questions) - Units III and IV.
from hrm_study_content1 import EG, FL, KEY, OL, P, T, UL

UNIT3 = ("UNIT III", "Development and Performance Management", "12 lectures - training and development, evaluating training, performance appraisal, career planning and succession", [
    ("3.1 Training and development",
     P("<b>Training</b> is a short-term, systematic effort to give employees the knowledge, skills and attitudes needed to do their <b>present job</b> better (Flippo: the act of increasing the knowledge and skill of an employee for doing a particular job). <b>Development</b> is a long-term, education-oriented process that prepares people for <b>future roles</b> and overall growth, with stress on conceptual and managerial ability.")
     + T(["Basis", "Training", "Development"], [["Focus", "Present job", "Future role"], ["Term", "Short-term", "Long-term"], ["Orientation", "Job / technical", "Career / conceptual"], ["Initiated by", "Organisation", "Individual and organisation"], ["Nature", "Specific and narrow", "Broad and general"]])
     + "<h4>Need and importance</h4>"
     + T(["For the organisation", "For the employee"], [[
         UL("Bridges the gap between required and actual skills and knowledge.", "Improves quality and productivity; reduces wastage, errors and accidents.", "Reduces the need for supervision.", "Prepares employees for change and higher responsibility.", "Strengthens competitiveness and supports succession planning.", "Lowers turnover."),
         UL("Helps adapt to new technology, processes and job demands.", "Raises morale, confidence and job satisfaction.", "Opens the way to career growth and promotion.")]])),
    ("3.2 The training process and identifying training needs",
     P("Training is a planned cycle, not a single event.")
     + FL("Assess organisational objectives", "Training needs assessment", "Set training goals", "Design the programme", "Execute the programme", "Evaluate results")
     + T(["Step", "What happens"], [["1. Organisational objectives and strategy", "Anchor training to the business, the quality wanted and the direction of the firm"], ["2. Training needs assessment", "Diagnose present and future gaps at three levels"], ["3. Training goals", "Set clear, measurable goals"], ["4. Design", "Choose content, methods, trainers, schedule and budget"], ["5. Execution", "Deliver the training as planned"], ["6. Evaluation", "Measure results and feed back into the next cycle"]])
     + "<h4>Training needs analysis (TNA) - three levels</h4>"
     + T(["Level", "Question it answers", "Source of information"], [["Organisational analysis", "Are business goals being met? Where are the overall performance gaps?", "Strategy, structure, climate, productivity and quality data"], ["Task analysis", "What knowledge, skills and standards does the job demand? (defines content)", "Job description and specification, task inventories"], ["Person analysis", "Who needs training, and what gap exists between current and required performance?", "Appraisal records, supervisor feedback, self-assessment, tests"]])),
    ("3.3 Methods of training",
     T(["On-the-job training (at the workplace)", "Off-the-job training (away from the workplace)"], [[
         UL("<b>Job rotation</b> - moving employees across jobs or departments to broaden skills.", "<b>Coaching</b> - a senior, usually the supervisor, guides and gives regular feedback.", "<b>Mentoring</b> - an experienced mentor gives long-term guidance and career advice; broader than coaching.", "<b>Apprenticeship</b> - a long structured programme of work plus instruction, leading to a certified qualification (skilled trades)."),
         UL("<b>Lectures</b> - instructor-led classroom sessions for concepts.", "<b>Case studies</b> - analysing real or imagined business situations.", "<b>Role play</b> - acting out work situations such as handling a difficult customer.", "<b>Simulation</b> - practice on a replica of equipment or situation, e.g. flight simulators.", "<b>Vestibule training</b> - a practice area near the workplace with the same machines, so production is not disturbed.")]])
     + T(["Basis", "On-the-job", "Off-the-job"], [["Location", "Actual workplace", "Away from the workplace"], ["Cost", "Generally lower", "Generally higher"], ["Disruption to work", "Higher", "Lower"], ["Strength", "Practical, no separate facility needed", "Focused learning, good for theory"], ["Weakness", "Quality depends on the trainer; can disturb work", "Skills may not transfer fully to the real job"]])),
    ("3.4 Evaluating training effectiveness",
     P("Training must be measured to know whether it worked. The most used framework is <b>Kirkpatrick's four-level model</b>.")
     + T(["Level", "What is measured", "How"], [["1. Reaction", "How participants felt - was it relevant, engaging, useful?", "Feedback forms immediately after training"], ["2. Learning", "Increase in knowledge or skill", "Pre-test and post-test"], ["3. Behaviour", "Whether the learning is applied on the job", "Observation and manager feedback after weeks or months"], ["4. Results", "Impact on the business - productivity, errors, sales, quality", "Organisational metrics"]])
     + P("Other approaches: <b>return on investment (ROI)</b> of training, comparing the money value of benefits with the cost; and <b>pre-test / post-test comparison</b> to quantify improvement.")),
    ("3.5 Performance appraisal",
     P("<b>Performance appraisal</b> is the systematic evaluation of an employee's job performance against pre-set standards, usually done once or twice a year. It is the main way an organisation judges how well people are doing and what to do about it.")
     + "<h4>Objectives</h4>"
     + UL("Provide a basis for promotion, increments and rewards.", "Identify training and development needs from performance gaps.", "Give employees structured feedback on strengths and weaknesses.", "<b>Validate selection</b> - check whether people hired are performing, which reflects on recruitment quality.", "Improve communication between managers and employees.", "Support succession planning and career decisions.")
     + "<h4>Methods</h4>"
     + T(["Traditional methods", "Modern methods"], [[
         UL("<b>Ranking</b> - employees ranked from best to worst; simple but does not show by how much they differ.", "<b>Graphic rating scale</b> - traits such as quality of work and punctuality rated on a scale (1-5).", "<b>Checklist</b> - yes / no or descriptive statements about behaviour.", "<b>Confidential reports</b> - the supervisor's private assessment, common in government and PSUs; little employee input."),
         UL("<b>Management by Objectives (MBO)</b> - manager and employee jointly set specific, measurable objectives; performance is judged against them. Stresses participation, clarity and results.", "<b>360-degree appraisal</b> - feedback from supervisors, peers, subordinates, self and sometimes customers; a complete picture.", "<b>BARS (Behaviourally Anchored Rating Scales)</b> - a numerical scale with a description of behaviour at each rating point, which reduces subjectivity.")]])
     + T(["Basis", "Traditional", "Modern"], [["Approach", "Trait-based, subjective", "Goal- and behaviour-based, more objective"], ["Employee involvement", "Minimal", "High (MBO, 360-degree)"], ["Feedback source", "Usually the supervisor alone", "Multiple sources"], ["Examples", "Ranking, graphic scale, checklist, confidential reports", "MBO, 360-degree, BARS"]])),
    ("3.6 Common biases in performance evaluation",
     P("Because appraisal rests on human judgment, it is prone to systematic errors.")
     + T(["Bias", "Meaning"], [["Halo effect", "A strong positive impression in one area (say punctuality) unfairly lifts ratings in unrelated areas"], ["Horn effect", "The opposite - one negative trait or incident drags down the whole rating"], ["Central tendency", "Rating almost everyone 'average' to avoid extreme scores or conflict"], ["Leniency / strictness", "Consistently rating higher (leniency) or lower (strictness) than deserved, making raters hard to compare"], ["Recency effect", "Giving too much weight to the latest weeks and ignoring the rest of the period"], ["Stereotyping", "Judging by assumptions about a group (gender, age, department) instead of individual performance"]])
     + P("<b>How to reduce bias:</b> clear and measurable standards, training for raters, multiple raters (360-degree), keeping records of performance through the year, and review of ratings by a higher authority.")),
    ("3.7 Career planning and development",
     P("<b>Career planning</b> is a deliberate process of becoming aware of one's skills, interests and values and setting goals for a desired career. <b>Career development</b> is the organisation's formal, ongoing activity (training, mentoring, job rotation) that links individual potential to organisational needs. Benefits: better retention, motivation, a talent pipeline and alignment of personal and organisational goals.")
     + "<h4>Stages of a career</h4>"
     + T(["Stage", "Roughly", "Focus"], [["1. Exploration", "Early 20s", "Discovering interests, abilities and values; trying different roles"], ["2. Establishment", "Mid-20s to mid-30s", "Choosing a path, building competence and credibility"], ["3. Mid-career", "Mid-30s to 50s", "Peak productivity and responsibility; continued growth or plateau; possible mid-career crisis"], ["4. Late career", "50s onward", "Becoming mentor, sharing expertise, preparing for exit"], ["5. Decline / disengagement", "Final stage", "Reduced involvement, retirement planning, handing over knowledge"]])),
    ("3.8 Succession planning and career management",
     P("<b>Succession planning</b> identifies and systematically develops internal talent to fill key leadership and critical positions in future, so that the organisation does not face a vacuum when someone retires, resigns or is promoted. High-potential employees are identified early and prepared through stretch assignments, mentoring and training.")
     + T(["Basis", "Individual career management", "Organisational career management"], [["Who drives it", "The employee", "The organisation (HR department)"], ["Focus", "Personal goals, self-assessment, building skills", "Meeting future talent and leadership needs"], ["Tools", "Self-assessment, networking, personal upskilling", "Succession planning, training, mentoring, career ladders"], ["Outcome", "Personal career satisfaction and growth", "A steady pipeline of capable people"]])),
])

UNIT4 = ("UNIT IV", "Compensation, Employee Welfare and Industrial Relations", "11 lectures - job evaluation, compensation, wage policy, welfare, industrial relations, disputes, collective bargaining, grievances", [
    ("4.1 Job evaluation",
     P("<b>Job evaluation</b> is the systematic process of determining the <b>relative worth of different jobs</b> in an organisation so that a fair and rational pay structure can be built. It evaluates the <b>job, not the person</b> holding it, and answers: which jobs should be paid more than others, and by how much?")
     + "<h4>Objectives</h4>"
     + UL("Establish a fair and equitable wage structure across jobs.", "Reduce wage grievances and disputes through objective, transparent criteria.", "Give a rational basis for pay differentials.")
     + "<h4>Methods</h4>"
     + T(["Method", "How it works", "Remark"], [["Ranking", "Whole jobs are compared and ranked from highest to lowest worth", "Simplest; impractical when jobs are many; shows no size of difference"], ["Job classification (grading)", "Jobs are slotted into predefined grades (Grade I, II, III) with descriptions", "Common in government and large organisations"], ["Point method", "Jobs are broken into compensable factors (skill, effort, responsibility, working conditions); points are given to each; total points decide worth and pay grade", "Most objective and widely used"], ["Factor comparison", "Key jobs with fair pay are benchmarks; other jobs are compared on the same factors", "More complex"], ["Hay Guide Chart-Profile", "Rates know-how, problem solving and accountability", "Used by consultants for managerial jobs"], ["Market pricing", "Worth is set by what the market pays for similar jobs", "External benchmark"]])
     + P("<b>Challenges:</b> subjectivity of ratings, time and cost, keeping evaluations current as jobs change, employee perceptions of unfairness, and matching internal values with market pay.")),
    ("4.2 Employee compensation",
     P("<b>Compensation</b> is the total package of financial and non-financial rewards an employee receives in return for work. It goes beyond the salary slip.")
     + "<h4>Objectives</h4>"
     + T(["Objective", "Meaning"], [["Internal equity", "Employees feel fairly paid relative to others doing comparable work in the firm"], ["External equity", "Pay is competitive with what other firms in the market pay for similar roles"], ["Attract and retain talent", "A sound pay structure draws capable people and holds high performers"], ["Motivate performance", "Incentive pay aligns effort with goals"], ["Legal compliance", "Follow laws such as the Minimum Wages Act"]])
     + "<h4>Components</h4>"
     + T(["Component", "Meaning", "Examples"], [["Base pay (basic salary)", "Fixed, guaranteed pay set by role, grade and experience; the base on which allowances and PF are calculated", "Monthly basic salary"], ["Incentives", "Variable, performance-linked pay that rewards results and fluctuates with performance", "Sales commission, productivity bonus, profit-sharing"], ["Fringe benefits", "Non-cash, indirect benefits in addition to pay; improve security and quality of life", "Health insurance, Provident Fund, paid leave, company vehicle, subsidised meals, housing allowance"]])),
    ("4.3 Wage policy, wage determination and wage boards",
     P("<b>Wage policy</b> is the set of guiding principles for fixing, revising and administering wages. A sound policy is fair, motivating, competitive, legal and financially sustainable.")
     + "<h4>Theories of wage determination</h4>"
     + T(["Theory", "Proponent", "Core idea"], [["Subsistence theory (Iron Law of Wages)", "David Ricardo", "Wages settle at the minimum needed for workers to survive and support their families; if wages rise, labour supply grows and pushes wages back down"], ["Wage fund theory", "Adam Smith / J. S. Mill", "Employers set aside a fixed fund of capital for wages; the average wage is the fund divided by the number of workers, so wages rise only if the fund grows or workers become fewer"], ["Bargaining theory of wages", "John Davidson", "Wages are not fixed by economic laws alone but by the relative bargaining power of employers and employees (unions), influenced by labour supply and ability to pay"]])
     + "<h4>Wage Board</h4>"
     + P("A <b>wage board</b> is a <b>tripartite</b> body of representatives of the government, employers and employees (trade unions) set up to study and recommend wages for a particular industry, for example textiles or the press. It makes wage fixing balanced rather than one-sided.")
     + "<h4>Factors influencing wage and salary administration</h4>"
     + T(["Factor", "Effect"], [["Demand and supply of labour", "Scarce, specialised skills earn more; abundant unskilled labour earns less"], ["Cost of living", "Wages need periodic revision, e.g. dearness allowance, to keep pace with inflation"], ["Ability to pay", "Financially strong firms can pay more"], ["Prevailing wage rates", "Firms benchmark pay against competitors in the industry"], ["Government legislation", "The Minimum Wages Act sets a legal floor"], ["Productivity", "Higher productivity supports higher wages"]])),
    ("4.4 Employee welfare",
     P("<b>Employee welfare</b> means the facilities and services given to employees over and above wages, to improve their health, safety, comfort and quality of life. It reduces absenteeism and turnover and builds loyalty.")
     + T(["Type", "Meaning", "Examples"], [["Statutory welfare", "Required by law", "Safe and clean workplace, drinking water, canteen, crèche, rest rooms, first-aid, washing facilities (Factories Act, 1948); provident fund, ESI, gratuity, maternity benefit"], ["Voluntary welfare", "Provided by the employer by choice", "Subsidised meals and transport, housing, medical care for family, recreation, scholarships for employees' children"], ["Mutual / union welfare", "Provided through unions or employee bodies", "Cooperative stores, credit societies, sports and cultural clubs"]])
     + "<h4>Important social security laws</h4>"
     + UL("<b>Employees' State Insurance Act, 1948</b> - medical, sickness, maternity and disability benefits.", "<b>Employees' Provident Funds Act, 1952</b> - retirement savings by employer and employee contributions.", "<b>Payment of Gratuity Act, 1972</b> - lump sum for long service.", "<b>Maternity Benefit Act, 1961</b> - paid leave and benefits for women.", "<b>Employees' Compensation Act (Workmen's Compensation, 1923)</b> - compensation for accident and occupational disease.")
     + P("<i>Note:</i> these laws are being brought together under the new Labour Codes; always quote the Act named in your class notes.")),
    ("4.5 Industrial relations",
     P("<b>Industrial relations (IR)</b> are the relationships between <b>employers, employees (and their unions) and the government</b>, covering negotiations, agreements, disputes and the whole work environment.")
     + "<h4>Parties to IR</h4>"
     + UL("<b>Employers</b> and their associations", "<b>Employees</b> and trade unions", "<b>Government</b> - makes labour laws and provides machinery for settling disputes")
     + "<h4>Importance of good IR</h4>"
     + UL("<b>Industrial peace</b> - fewer strikes, lockouts and disruptions.", "<b>Higher productivity</b> - a cooperative atmosphere helps smooth operations.", "<b>Less conflict</b> - structured ways of settling disagreements.", "<b>Economic and social stability</b> - large-scale unrest harms the wider economy.")
     + "<h4>Approaches to IR</h4>"
     + T(["Approach", "Idea"], [["Unitary", "Management and workers share the same interests; unions are unnecessary; conflict is abnormal"], ["Pluralist", "Different groups with different interests; conflict is natural and is managed by bargaining"], ["Marxist / radical", "Conflict arises from the capital-labour divide"]])),
    ("4.6 Industrial disputes",
     P("An <b>industrial dispute</b> is a conflict or difference of opinion between employers and employees (or their representatives) about terms of employment, conditions of work, or the rights and duties of either side. In India it is governed by the <b>Industrial Disputes Act, 1947</b>.")
     + T(["Form of dispute", "Meaning"], [["Strike", "Collective, organised refusal by employees to work, to press demands"], ["Lockout", "Temporary closing of the workplace, or refusal to let employees work, by the employer"], ["Gherao", "Workers surround management and do not let them leave"], ["Picketing and go-slow", "Peaceful demonstration at the gate; deliberately slow work"]])
     + "<h4>Causes</h4>"
     + UL("<b>Economic</b> - low wages, bonus, allowances, working hours.", "<b>Managerial</b> - poor communication, unfair policies, victimisation.", "<b>Political and legal</b> - union rivalry, outside influence, labour law changes.", "<b>Social and psychological</b> - lack of recognition, bad supervision, poor working conditions.")
     + "<h4>Prevention and settlement machinery</h4>"
     + T(["Preventive", "Settlement"], [[
         UL("Works committees (in establishments with 100 or more workmen)", "Grievance Redressal Committees (20 or more workers)", "Collective bargaining and bipartite agreements", "Code of Discipline and standing orders", "Workers' participation in management"),
         UL("<b>Conciliation</b> - Conciliation Officer / Board of Conciliation helps the parties reach agreement.", "<b>Court of Inquiry</b> - investigates and reports.", "<b>Arbitration</b> - voluntary reference to a neutral arbitrator whose award is binding.", "<b>Adjudication</b> - Labour Court, Industrial Tribunal, National Tribunal decide the dispute.")]])),
    ("4.7 Collective bargaining",
     P("<b>Collective bargaining</b> is the process in which an employer (or employers' association) and a group of employees, usually represented by a trade union, negotiate wages, hours and other conditions of work to reach a <b>mutual agreement</b> instead of one side deciding alone.")
     + "<h4>Features</h4>"
     + UL("It is a <b>negotiation</b>, not a one-sided decision - flexible, dynamic and continuous.", "It ends in a <b>collective agreement</b> binding on both parties for an agreed period.", "It balances management's concern for efficiency and cost with employees' concern for fair treatment.", "It is <b>bipartite</b> - employer and employees negotiate without outside decision (a third party may help).")
     + "<h4>Process</h4>"
     + FL("Preparation and fact collection", "Identify issues and demands", "Negotiation", "Agreement", "Implementation and review")
     + P("<b>Importance:</b> it gives workers a collective voice, brings stability to wage and service conditions, and reduces strikes and lockouts.")),
    ("4.8 Grievance handling machinery",
     P("A <b>grievance</b> is any discontent or dissatisfaction, expressed or not, arising from anything connected with the employee's job that the employee thinks is unfair. <b>Grievance handling machinery</b> is the formal system to raise, escalate and resolve such complaints quickly and fairly, before they grow into disputes.")
     + T(["Approach", "How it works", "Merit / limitation"], [["Open door policy", "Employees approach senior management directly without going through many levels", "Quick and builds trust; impractical in large organisations"], ["Step-ladder procedure", "The grievance moves up if unresolved at each level", "Orderly and recorded; slower"]])
     + FL("Employee to immediate supervisor", "Department head", "HR / Grievance Committee", "Top management or arbitration (in unionised firms)")
     + P("<b>Principles of a good system:</b> easy to use, prompt, fair, confidential, no victimisation, and with a right to appeal. A well-run system settles problems early and supports industrial peace.")),
])
